+  formatted = formatted.split('\n').map(line => {
+    let trimmed = line.trim();
+    if (trimmed.startsWith('*')) {
+      const content = trimmed.substring(1).trim();
+      return `• ${content}`;
+    }
+    return line;
+  }).join('\n');
+  
+  return formatted;
